def e_wert(rr):
    """E-Wert nach VanderWeele und Ding (2017) für ein Verhältnis; unter 1 wird es zuerst umgedreht."""
    rr = 1 / rr if rr < 1 else rr
    return rr + np.sqrt(rr * (rr - 1))


print(round(e_wert(0.851), 3), round(e_wert(0.920), 3))
